export function parseStakeInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedStakeInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 22) {
    // TODO: Coded error.
    throw new Error("Not enough accounts")
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount()
    return accountMeta.address === STAKE_PROGRAM_ADDRESS ? undefined : accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      staker: getNextAccount(),
      collection: getNextAccount(),
      nftRecord: getNextOptionalAccount(),
      stakeRecord: getNextAccount(),
      programConfig: getNextAccount(),
      nftMint: getNextAccount(),
      nftToken: getNextAccount(),
      nftMetadata: getNextAccount(),
      nftEdition: getNextAccount(),
      ownerTokenRecord: getNextOptionalAccount(),
      destinationTokenRecord: getNextOptionalAccount(),
      nftAuthority: getNextAccount(),
      nftCustody: getNextOptionalAccount(),
      signer: getNextAccount(),
      feesWallet: getNextAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      metadataProgram: getNextAccount(),
      sysvarInstructions: getNextAccount(),
      authRules: getNextOptionalAccount(),
      authRulesProgram: getNextOptionalAccount(),
    },
    data: getStakeInstructionDataDecoder().decode(instruction.data),
  }
}
